import unittest

import launch
import launch_ros.actions
import launch_testing.actions
import launch_testing.markers
import pytest
import rclpy
from rclpy.node import Node
from std_msgs.msg import Int32


@pytest.mark.launch_test
def generate_test_description():
    echo_node = launch_ros.actions.Node(
        package='echo_pkg',
        executable='echo_node',
        name='echo_node',
    )

    return launch.LaunchDescription([
        echo_node,
        launch_testing.actions.ReadyToTest(),
    ]), {'echo_node': echo_node}


class TestEchoNodeLink(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        rclpy.init()

    @classmethod
    def tearDownClass(cls):
        rclpy.shutdown()

    def setUp(self):
        self.node = Node('test_echo_node')

    def tearDown(self):
        self.node.destroy_node()

    def test_value_echoed_to_out(self, proc_output):
        received = []

        def callback(msg):
            received.append(msg.data)

        sub = self.node.create_subscription(Int32, '/out', callback, 10)
        pub = self.node.create_publisher(Int32, '/in', 10)

        try:
            # Wait for the publisher/subscriber to discover each other and
            # the node to be up before sending the test value.
            end_time = self.node.get_clock().now().nanoseconds + 10 * 1e9
            msg = Int32()
            msg.data = 42

            while self.node.get_clock().now().nanoseconds < end_time:
                if not received:
                    pub.publish(msg)
                rclpy.spin_once(self.node, timeout_sec=0.5)
                if received:
                    break

            self.assertTrue(len(received) > 0, 'No message received on /out')
            self.assertEqual(received[0], 42)
        finally:
            self.node.destroy_publisher(pub)
            self.node.destroy_subscription(sub)


@launch_testing.post_shutdown_test()
class TestEchoNodeShutdown(unittest.TestCase):

    def test_exit_code(self, proc_info, echo_node):
        launch_testing.asserts.assertExitCodes(proc_info, process=echo_node)

